export async function listTools() {
  return [
    {
      name: 'batch_lookup',
      description: 'Look up multiple ids in one batch. Returns one result per id in input order; missing ids are reported per-item without aborting the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
          },
        },
        required: ['ids'],
        additionalProperties: false,
      },
    },
  ];
}

function fail(code, message) {
  const err = new Error(message);
  err.code = code;
  return err;
}

export async function callTool(name, args = {}) {
  if (name !== 'batch_lookup') {
    throw fail(-32601, `Unknown tool: ${name}`);
  }
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw fail(-32602, 'Arguments must be an object');
  }
  const keys = Object.keys(args);
  if (keys.length !== 1 || keys[0] !== 'ids') {
    throw fail(-32602, 'Invalid arguments: expected only "ids"');
  }
  const { ids } = args;
  if (!Array.isArray(ids) || ids.length === 0) {
    throw fail(-32602, '"ids" must be a non-empty array');
  }
  for (const id of ids) {
    if (typeof id !== 'string') {
      throw fail(-32602, '"ids" must be an array of strings');
    }
  }
  const results = ids.map((id) => {
    if (Object.prototype.hasOwnProperty.call(KNOWN, id)) {
      return { id, ok: true, value: KNOWN[id] };
    }
    return { id, ok: false, error: `Unknown id: ${id}` };
  });
  return {
    content: [{ type: 'text', text: JSON.stringify({ results }) }],
  };
}
